// RoadShield Vision HUD over a real road photograph (Wikimedia Commons, credited).
// The boxes, labels, confidences and inference time are the REAL output of the production
// detector on this exact image (src/lib/vision-samples.json, regenerated by
// scripts/assets/run-vision-samples.py). Nothing on the overlay is invented.
import Image from 'next/image';
import { Cpu, Timer, Crosshair, EyeOff, ShieldCheck, Layers, Fingerprint, Download, MapPinned } from 'lucide-react';
import type { Locale } from '@/lib/i18n/dict';
import samples from '@/lib/vision-samples.json';

type Det = { label: string; category: string; confidence: number; box: number[] };
export type Sample = { src: string; width: number; height: number; inference_ms: number; detections: Det[];
  credit: { title: string; author: string; licence: string; licence_url: string | null; source: string; changes: string } };

export const CLASS_CODE: Record<string, string> = { 'Longitudinal Crack': 'D00', 'Transverse Crack': 'D10', 'Alligator Crack': 'D20', Potholes: 'D40' };
const LABEL = {
  en: { 'Longitudinal Crack': 'Longitudinal crack', 'Transverse Crack': 'Transverse crack', 'Alligator Crack': 'Alligator crack', Potholes: 'Pothole' },
  ar: { 'Longitudinal Crack': 'شرخ طولي', 'Transverse Crack': 'شرخ عرضي', 'Alligator Crack': 'تشقق تمساحي', Potholes: 'حفرة' },
} as const;
export const detLabel = (l: Locale, d: string) => (LABEL[l] as Record<string, string>)[d] ?? d;
export const confColor = (c: number) => (c >= 0.6 ? '#E5484D' : c >= 0.5 ? '#F5A524' : '#51C7F5');

const T = {
  en: { model: 'Model', inference: 'Inference', detections: 'Detections', privacy: 'Privacy', review: 'Review', blurred: 'Faces & plates blurred',
    required: 'Engineer confirms', classes: 'Classes', signed: 'Result', signedV: 'HMAC-signed', suggested: 'Suggested category', confidence: 'Model confidence',
    threshold: 'Below 0.50 → flagged for review', network: 'Network view', export: 'Export', real: 'Real model output on this photo', photo: 'Photo',
    flagged: 'Flagged for review', scan: 'RoadShield Vision · analysis', cpu: 'CPU' },
  ar: { model: 'النموذج', inference: 'زمن التحليل', detections: 'الرصد', privacy: 'الخصوصية', review: 'المراجعة', blurred: 'تمويه الوجوه واللوحات',
    required: 'يؤكدها المهندس', classes: 'الفئات', signed: 'النتيجة', signedV: 'موقّعة HMAC', suggested: 'الفئة المقترحة', confidence: 'ثقة النموذج',
    threshold: 'أقل من 0.50 ← تُحال للمراجعة', network: 'عرض الشبكة', export: 'التصدير', real: 'مخرجات حقيقية للنموذج على هذه الصورة', photo: 'الصورة',
    flagged: 'محالة للمراجعة', scan: 'رود شيلد فيجن · تحليل', cpu: 'معالج' },
};

export function Boxes({ dets, locale, size = 'md' }: { dets: Det[]; locale: Locale; size?: 'sm' | 'md' }) {
  return (
    <>
      {dets.map((d, i) => {
        const [x1, y1, x2, y2] = d.box as [number, number, number, number];
        const c = confColor(d.confidence);
        return (
          <div key={i} className="absolute" style={{ left: `${x1 * 100}%`, top: `${y1 * 100}%`, width: `${(x2 - x1) * 100}%`, height: `${(y2 - y1) * 100}%` }}>
            <div className="absolute inset-0 rounded-[3px]" style={{ border: `2px solid ${c}`, background: `${c}14`, boxShadow: `0 0 0 1px rgba(0,0,0,.35)` }} />
            {[['top-0 left-0', 'border-t-[3px] border-l-[3px]'], ['top-0 right-0', 'border-t-[3px] border-r-[3px]'], ['bottom-0 left-0', 'border-b-[3px] border-l-[3px]'], ['bottom-0 right-0', 'border-b-[3px] border-r-[3px]']].map(([pos, b]) => (
              <span key={pos} className={`absolute ${pos} ${b} size-3`} style={{ borderColor: '#fff' }} />
            ))}
            {/* Label sits above the box; it moves inside when the box touches the top edge, and
                right-aligns when the box is near the right edge, so it is never clipped. */}
            <div className={`hud-panel absolute whitespace-nowrap ${y1 < 0.14 ? 'top-1.5' : 'bottom-full mb-1.5'} ${x1 > 0.6 ? 'right-0' : 'left-0'} ${size === 'sm' ? 'px-2 py-1 text-[10px]' : 'px-2.5 py-1.5 text-[11.5px]'}`} style={{ borderColor: `${c}99` }}>
              <p className="font-[650] uppercase tracking-wide">{CLASS_CODE[d.label]} · {detLabel(locale, d.label)}</p>
              <p className="tabular" style={{ color: c }}>{d.confidence.toFixed(2)}</p>
            </div>
          </div>
        );
      })}
    </>
  );
}

function NetworkLines() {
  const segs = [['M4 70 L40 52 L64 40 L96 18', '#12A879'], ['M10 8 L34 30 L52 46 L70 64 L92 78', '#F5A524'], ['M52 46 L58 72 L62 92', '#E5484D'],
    ['M34 30 L44 6', '#12A879'], ['M64 40 L88 48', '#00B8A9'], ['M18 88 L40 52', '#8D99AB']] as const;
  return (
    <svg viewBox="0 0 100 96" className="h-24 w-full rounded-md bg-[#0a121d]" aria-hidden>
      {Array.from({ length: 6 }).map((_, i) => <path key={i} d={`M0 ${i * 18} H100 M${i * 20} 0 V96`} stroke="#fff" strokeOpacity=".04" />)}
      {segs.map(([d, c]) => <path key={d} d={d} stroke={c} strokeWidth="2.4" fill="none" strokeLinecap="round" />)}
      <circle cx="52" cy="46" r="4" fill="#fff" /><circle cx="52" cy="46" r="7" fill="none" stroke="#fff" strokeOpacity=".4" />
    </svg>
  );
}

export function ScanHud({ locale, sampleKey = 'scan-road-fl' }: { locale: Locale; sampleKey?: string }) {
  const t = T[locale];
  const s = (samples.photos as Record<string, Sample>)[sampleKey]!;
  const top = [...s.detections].sort((a, b) => b.confidence - a.confidence)[0];
  const cell = (Icon: typeof Cpu, k: string, v: React.ReactNode) => (
    <div className="flex min-w-0 items-center gap-2.5 px-3 lg:px-4">
      <Icon size={19} strokeWidth={1.5} className="shrink-0 text-white/75" />
      <div className="min-w-0"><p className="text-[9.5px] font-[600] uppercase tracking-[0.12em] text-white/50">{k}</p><p className="truncate text-[14px] font-[560] text-white tabular">{v}</p></div>
    </div>
  );
  return (
    <figure className="relative">
      <div className="relative overflow-hidden rounded-[18px] border border-white/10 bg-black shadow-[0_40px_120px_-30px_rgba(0,0,0,0.85)]" dir="ltr">
        <div className="relative aspect-[16/9] w-full">
          <Image src={s.src} alt="" fill priority sizes="(min-width: 1280px) 1200px, 100vw" className="object-cover" />
          <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/25" />
          <Boxes dets={s.detections} locale={locale} />
          <div className="hud-panel absolute inset-x-3 top-3 hidden grid-cols-5 divide-x divide-white/10 py-2.5 md:grid">
            {cell(Cpu, t.model, 'YOLOv8s · RDD2022')}
            {cell(Timer, t.inference, `${s.inference_ms} ms · ${t.cpu}`)}
            {cell(Crosshair, t.detections, String(s.detections.length))}
            {cell(EyeOff, t.privacy, t.blurred)}
            {cell(ShieldCheck, t.review, t.required)}
          </div>
          <div className="absolute start-3 top-[24%] hidden w-[18%] min-w-[160px] lg:block">
            <div className="hud-panel divide-y divide-white/10 text-[11px]">
              {([[Layers, t.classes, 'D00 · D10 · D20 · D40'], [Fingerprint, t.signed, t.signedV], [MapPinned, 'GPS', locale === 'ar' ? 'من الهاتف' : 'From the phone']] as const).map(([I, k, v]) => (
                <div key={k} className="flex gap-2.5 px-3 py-2.5">
                  <I size={15} strokeWidth={1.6} className="mt-0.5 shrink-0 text-white/65" />
                  <div><p className="text-[9.5px] uppercase tracking-[0.1em] text-white/50">{k}</p><p className="mt-0.5 text-[12.5px] text-white">{v}</p></div>
                </div>
              ))}
            </div>
          </div>
          {top ? (
            <div className="absolute end-3 top-[24%] hidden w-[20%] min-w-[180px] flex-col gap-2 lg:flex">
              <div className="hud-panel px-3 py-2.5">
                <p className="text-[9.5px] uppercase tracking-[0.1em] text-white/50">{t.suggested}</p>
                <p className="mt-1 text-[17px] font-[600]">{CLASS_CODE[top.label]} · {detLabel(locale, top.label)}</p>
              </div>
              <div className="hud-panel px-3 py-2.5">
                <p className="text-[9.5px] uppercase tracking-[0.1em] text-white/50">{t.confidence}</p>
                <p className="mt-1 text-[22px] font-[620] tabular" style={{ color: confColor(top.confidence) }}>{top.confidence.toFixed(2)}</p>
                <div className="relative mt-2 h-1.5 rounded-full bg-white/10">
                  <div className="h-full rounded-full" style={{ width: `${top.confidence * 100}%`, background: confColor(top.confidence) }} />
                  <span className="absolute -top-1 h-3.5 w-px bg-white" style={{ left: '50%' }} />
                </div>
                <p className="mt-1.5 text-[10.5px] text-white/60">{top.confidence < 0.5 ? `⚑ ${t.flagged}` : t.threshold}</p>
              </div>
              <div className="hud-panel px-3 py-2.5"><p className="mb-1.5 text-[9.5px] uppercase tracking-[0.1em] text-white/50">{t.network}</p><NetworkLines /></div>
              <div className="hud-panel flex items-start gap-2 px-3 py-2.5 text-[11px]"><Download size={14} className="mt-0.5 text-white/65" /><div><p className="text-[9.5px] uppercase tracking-[0.1em] text-white/50">{t.export}</p><p className="text-white/90">CSV · GeoJSON</p></div></div>
            </div>
          ) : null}
          <div className="absolute bottom-3 start-1/2 hidden -translate-x-1/2 items-center gap-2 whitespace-nowrap rounded-full sm:flex bg-black/60 px-3 py-1 text-[11px] text-white/85 backdrop-blur">
            <span className="size-1.5 rounded-full bg-[#12A879]" />{t.scan}
          </div>
        </div>
      </div>
      <figcaption className="mt-3 text-center text-[11px] leading-relaxed text-white/45">
        {t.real} · {t.photo}: <a href={s.credit.source} className="underline decoration-white/20 hover:text-white/70" target="_blank" rel="noreferrer">“{s.credit.title.replace(/^File:/, '').replace(/\.jpe?g$/i, '')}”</a> — {s.credit.author}, {s.credit.licence} ({s.credit.changes})
      </figcaption>
    </figure>
  );
}
